import SwiftUI

/// An open-source component shipped inside the app, generated by `just licenses`.
struct License: Decodable, Identifiable, Hashable {
    let name: String
    let url: URL
    let license: String
    let text: String

    var id: String { name }

    static let all: [License] = {
        guard let url = Bundle.main.url(forResource: "licenses", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let licenses = try? JSONDecoder().decode([License].self, from: data)
        else { return [] }
        return licenses
    }()
}

/// Everything Bergr ships that others wrote, with their licenses.
struct LicensesView: View {
    var body: some View {
        List {
            Section {
                ForEach(License.all) { license in
                    // A direct link: a value link needs a navigationDestination on the stack's root,
                    // and this page is itself pushed (from Settings), so it showed a ⚠️ placeholder.
                    NavigationLink {
                        LicenseView(license: license)
                    } label: {
                        VStack(alignment: .leading, spacing: 2) {
                            Text(license.name)
                            Text(license.license).font(.caption).foregroundStyle(.secondary)
                        }
                    }
                }
            } footer: {
                Text("Bergr is built on these projects. Thank you to their authors.")
            }
        }
        .navigationTitle("Open-Source Licenses")
        .inlineNavigationTitle()
    }
}

struct LicenseView: View {
    let license: License

    var body: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 12) {
                Link(license.url.absoluteString, destination: license.url)
                    .font(.footnote)
                Text(license.text)
                    .font(.system(.caption, design: .monospaced))
                    .textSelection(.enabled)
            }
            .frame(maxWidth: .infinity, alignment: .leading)
            .padding()
        }
        .navigationTitle(license.name)
        .inlineNavigationTitle()
    }
}

#Preview {
    NavigationStack { LicensesView() }
